from scipy.optimize import least_squares
def build(w):
    cs=np.cos(w*t); sn=np.sin(w*t)
    return np.column_stack([cs,sn,np.ones_like(x),x,v,v*cs,v*sn,v*np.abs(v)])
def R(w):
    A=build(w); c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]; return dv_dt-A@c, c
r=least_squares(lambda p: R(p[0])[0], [0.392])
w=r.x[0]; rr,c=R(w)
print('w',w,'R2',1-np.sum(rr**2)/np.sum((dv_dt-dv_dt.mean())**2), np.round(c,4))
print('rms resid',np.sqrt(np.mean(rr**2)))
# residual vs features
feats={'t':t,'x':x,'v':v,'cos':np.cos(w*t),'sin':np.sin(w*t),'xv':x*v,'x2':x*x,'v2':v*v,'vabsv':v*np.abs(v),'v3':v**3,'x3':x**3,'xcos':x*np.cos(w*t),'xsin':x*np.sin(w*t),'vxcos':v*x*np.cos(w*t),'vxsin':v*x*np.sin(w*t),'t2':t*t,'tv':t*v,'tx':t*x}
for k,f in feats.items():
    print(k, round(np.corrcoef(f,rr)[0,1],3))
print(np.round(np.sort(rr)[[0,1,2,-3,-2,-1]],3))
